/**
 * Find Duplicate Subtrees
 *
 * Given the root of a binary tree, return all duplicate subtrees.
 * Two trees are duplicate if they have the same structure and node values.
 * Returns an array of root nodes of duplicate subtrees.
 */
function findDuplicates(root) {
  const count = new Map();
  const result = [];

  function serialize(node) {
    if (!node) return '#';
    const key = `${node.val},${serialize(node.left)},serialize(node.right)}`;
    count.set(key, (count.get(key) || 0) + 1);
    if (count.get(key) === 2) result.push(node);
    return key;
  }

  serialize(root);
  return result;
}

// --- Serialize/Deserialize binary tree to/from string ---

function serialize(root) {
  if (!root) return 'null';
  return `${root.val},${serialize(root.left)},serialize(root.right)}`;
}

function deserialize(data) {
  const tokens = data.split(',');
  let i = 0;

  function build() {
    if (tokens[i] === 'null') { i++; return null; }
    const node = new TreeNode(parseInt(tokens[i++]));
    node.left = build();
    node.right = build();
    return node;
  }

  return build();
}

// --- Helper: array to tree (level-order) ---
class TreeNode {
  constructor(val, left, right) {
    this.val = val === undefined ? 0 : val;
    this.left = left === undefined ? null : left;
    this.right = right === undefined ? null : right;
  }
}

function arrayToTree(arr) {
  if (!arr || arr.length === 0) return null;
  const root = new TreeNode(arr[0]);
  const queue = [root];
  let i = 1;
  while (queue.length > 0 && i < arr.length) {
    const node = queue.shift();
    if (i < arr.length && arr[i] !== null) {
      node.left = new TreeNode(arr[i]);
      queue.push(node.left);
    }
    i++;
    if (i < arr.length && arr[i] !== null) {
      node.right = new TreeNode(arr[i]);
      queue.push(node.right);
    }
    i++;
  }
  return root;
}

// --- Tests ---

function runTests() {
  let passed = 0;
  let failed = 0;

  function assert(condition, name) {
    if (condition) { passed++; console.log(`  PASS: ${name}`); }
    else { failed++; console.error(`  FAIL: ${name}`); }
  }

  function treeEquals(a, b) {
    if (!a && !b) return true;
    if (!a || !b) return false;
    return a.val === b.val && treeEquals(a.left, b.left) && treeEquals(a.right, b.right);
  }

  console.log('=== findDuplicates ===');

  // Test 1: duplicates found
  {
    //       1
    //      / \
    //     2   3
    //    /   / \
    //   4   2   4
    //      /
    //     4
    const root = arrayToTree([1, 2, 3, 4, null, 2, 4, null, null, 4]);
    const dupes = findDuplicates(root);
    assert(dupes.length === 2, 'Test 1: finds 2 duplicate subtree groups');
  }

  // Test 2: no duplicates
  {
    const root = arrayToTree([1, 2, 3]);
    const dupes = findDuplicates(root);
    assert(dupes.length === 0, 'Test 2: no duplicates in simple tree');
  }

  // Test 3: empty tree
  {
    const dupes = findDuplicates(null);
    assert(dupes.length === 0, 'Test 3: empty tree has no duplicates');
  }

  // Test 4: single node
  {
    const root = new TreeNode(1);
    const dupes = findDuplicates(root);
    assert(dupes.length === 0, 'Test 4: single node has no duplicates');
  }

  // Test 5: all same values
  {
    //     1
    //    / \
    //   1   1
    const root = arrayToTree([1, 1, 1]);
    const dupes = findDuplicates(root);
    assert(dupes.length === 1, 'Test 5: duplicate leaf subtrees');
    assert(dupes[0].val === 1, 'Test 5: duplicate root value is 1');
  }

  console.log('\n=== serialize / deserialize ===');

  // Test 6: roundtrip
  {
    const root = arrayToTree([1, 2, 3, null, null, 4, 5]);
    const s = serialize(root);
    const back = deserialize(s);
    assert(treeEquals(root, back), 'Test 6: serialize->deserialize roundtrip');
  }

  // Test 7: empty tree roundtrip
  {
    const s = serialize(null);
    assert(s === 'null', 'Test 7: null serializes to "null"');
    assert(deserialize('null') === null, 'Test 7: "null" deserializes to null');
  }

  // Test 8: single node roundtrip
  {
    const root = new TreeNode(42);
    const back = deserialize(serialize(root));
    assert(back.val === 42 && !back.left && !back.right, 'Test 8: single node roundtrip');
  }

  // Test 9: left-skewed tree
  {
    const root = arrayToTree([1, 2, null, 3]);
    const back = deserialize(serialize(root));
    assert(treeEquals(root, back), 'Test 9: left-skewed tree roundtrip');
  }

  // Test 10: right-skewed tree
  {
    const root = arrayToTree([1, null, 2, null, null, null, 3]);
    const back = deserialize(serialize(root));
    assert(treeEquals(root, back), 'Test 10: right-skewed tree roundtrip');
  }

  console.log(`\n${passed} passed, ${failed} failed`);
  return failed === 0;
}

runTests();

