"use strict";

class TreeNode {
  constructor(val, left, right) {
    this.val = val === undefined ? 0 : val;
    this.left = left === undefined ? null : left;
    this.right = right === undefined ? null : right;
  }
}

/**
 * Serialize a binary tree to a string (pre-order, comma-separated).
 * Null children are represented as '#'.
 */
function serialize(root) {
  if (!root) return '#';
  return root.val + ',' + serialize(root.left) + ',' + serialize(root.right);
}

/**
 * Deserialize a string back into a binary tree.
 */
function deserialize(data) {
  var tokens = data.split(',');
  var i = 0;
  function build() {
    if (tokens[i] === '#') { i++; return null; }
    var node = new TreeNode(parseInt(tokens[i++], 10));
    node.left = build();
    node.right = build();
    return node;
  }
  return build();
}

/**
 * Find all duplicate subtrees in a binary tree.
 *
 * Returns an array of root nodes — one representative per duplicate group.
 * Each subtree appears in the result only once even if it occurs more than twice.
 */
function find_duplicates(root) {
  var count = Object.create(null);
  var result = [];

  function dfs(node) {
    if (!node) return '#';
    var key = node.val + ',' + dfs(node.left) + ',' + dfs(node.right);
    count[key] = (count[key] || 0) + 1;
    if (count[key] === 2) result.push(node);
    return key;
  }

  dfs(root);
  return result;
}

module.exports = { TreeNode, serialize, deserialize, find_duplicates };

"use strict";

var assert = require('assert');
var m = require('./find_duplicates');
var TreeNode = m.TreeNode;
var serialize = m.serialize;
var deserialize = m.deserialize;
var find_duplicates = m.find_duplicates;

// --- helpers ---

function arrayToTree(arr) {
  if (!arr || arr.length === 0) return null;
  var root = new TreeNode(arr[0]);
  var queue = [root];
  var i = 1;
  while (queue.length > 0 && i < arr.length) {
    var node = queue.shift();
    if (i < arr.length && arr[i] !== null && arr[i] !== undefined) {
      node.left = new TreeNode(arr[i]);
      queue.push(node.left);
    }
    i++;
    if (i < arr.length && arr[i] !== null && arr[i] !== undefined) {
      node.right = new TreeNode(arr[i]);
      queue.push(node.right);
    }
    i++;
  }
  return root;
}

function treeToArray(root) {
  if (!root) return [];
  var result = [];
  var queue = [root];
  while (queue.length > 0) {
    var node = queue.shift();
    if (node) {
      result.push(node.val);
      queue.push(node.left);
      queue.push(node.right);
    } else {
      result.push(null);
    }
  }
  // trim trailing nulls
  while (result.length > 0 && result[result.length - 1] === null) result.pop();
  return result;
}

function sortedVals(nodes) {
  return nodes.map(function (n) { return n.val; }).sort(function (a, b) { return a - b; });
}

// --- serialize / deserialize ---

var tests = [
  {
    name: 'serialize: null tree',
    fn: function () {
      assert.strictEqual(serialize(null), '#');
    }
  },
  {
    name: 'serialize: single node',
    fn: function () {
      assert.strictEqual(serialize(new TreeNode(5)), '5,#,#');
    }
  },
  {
    name: 'serialize: left and right children',
    fn: function () {
      var root = new TreeNode(1, new TreeNode(2), new TreeNode(3));
      assert.strictEqual(serialize(root), '1,2,#,#,3,#,#');
    }
  },
  {
    name: 'deserialize: null string',
    fn: function () {
      assert.strictEqual(deserialize('#'), null);
    }
  },
  {
    name: 'deserialize: single node',
    fn: function () {
      var node = deserialize('42,#,#');
      assert.strictEqual(node.val, 42);
      assert.strictEqual(node.left, null);
      assert.strictEqual(node.right, null);
    }
  },
  {
    name: 'roundtrip: simple tree',
    fn: function () {
      var root = new TreeNode(1, new TreeNode(2), new TreeNode(3));
      var back = deserialize(serialize(root));
      assert.deepStrictEqual(treeToArray(back), [1, 2, 3]);
    }
  },
  {
    name: 'roundtrip: left-skewed',
    fn: function () {
      var root = arrayToTree([1, 2, null, 3]);
      var back = deserialize(serialize(root));
      assert.deepStrictEqual(treeToArray(back), treeToArray(root));
    }
  },
  {
    name: 'roundtrip: right-skewed',
    fn: function () {
      var root = arrayToTree([1, null, 2, null, null, null, 3]);
      var back = deserialize(serialize(root));
      assert.deepStrictEqual(treeToArray(back), treeToArray(root));
    }
  },
  {
    name: 'roundtrip: complex tree',
    fn: function () {
      var root = arrayToTree([5, 3, 8, 1, 4, 7, 9, null, 2]);
      var back = deserialize(serialize(root));
      assert.deepStrictEqual(treeToArray(back), treeToArray(root));
    }
  },
  {
    name: 'roundtrip: large values',
    fn: function () {
      var root = new TreeNode(100000, new TreeNode(-999), new TreeNode(0));
      var back = deserialize(serialize(root));
      assert.deepStrictEqual(treeToArray(back), [100000, -999, 0]);
    }
  },
  {
    name: 'roundtrip: deep tree preserves structure',
    fn: function () {
      // depth 5: 1 -> 2 -> 3 -> 4 -> 5
      var n5 = new TreeNode(5);
      var n4 = new TreeNode(4, n5, null);
      var n3 = new TreeNode(3, n4, null);
      var n2 = new TreeNode(2, n3, null);
      var n1 = new TreeNode(1, n2, null);
      var back = deserialize(serialize(n1));
      assert.deepStrictEqual(treeToArray(back), treeToArray(n1));
    }
  },

  // --- find_duplicates ---

  {
    name: 'find_duplicates: empty tree',
    fn: function () {
      assert.deepStrictEqual(find_duplicates(null), []);
    }
  },
  {
    name: 'find_duplicates: single node, no duplicates',
    fn: function () {
      assert.deepStrictEqual(find_duplicates(new TreeNode(1)), []);
    }
  },
  {
    name: 'find_duplicates: no duplicates in [1,2,3]',
    fn: function () {
      assert.deepStrictEqual(find_duplicates(arrayToTree([1, 2, 3])), []);
    }
  },
  {
    name: 'find_duplicates: duplicate leaf subtrees',
    fn: function () {
      //     1
      //    / \
      //   2   2
      var root = arrayToTree([1, 2, 2]);
      var dupes = find_duplicates(root);
      assert.strictEqual(dupes.length, 1);
      assert.strictEqual(dupes[0].val, 2);
    }
  },
  {
    name: 'find_duplicates: duplicate subtree with children',
    fn: function () {
      //       1
      //      / \
      //     2   3
      //    /   / \
      //   4   2   4
      //      /
      //     4
      var root = arrayToTree([1, 2, 3, 4, null, 2, 4, null, null, 4]);
      var dupes = find_duplicates(root);
      assert.strictEqual(dupes.length, 2);
      var vals = sortedVals(dupes);
      assert.deepStrictEqual(vals, [2, 4]);
    }
  },
  {
    name: 'find_duplicates: three copies returns one representative',
    fn: function () {
      //     2
      //    / \
      //   1   1
      //  /   / \
      // 1   1   1  (three leaf 1s)
      var root = arrayToTree([2, 1, 1, 1, null, 1, 1]);
      var dupes = find_duplicates(root);
      // leaf node 1 is duplicated (count >= 2), reported once
      assert.ok(dupes.length >= 1, 'at least one duplicate group');
    }
  },
  {
    name: 'find_duplicates: right-skewed no duplicates',
    fn: function () {
      var root = arrayToTree([1, null, 2, null, null, null, 3]);
      assert.deepStrictEqual(find_duplicates(root), []);
    }
  },
  {
    name: 'find_duplicates: both left and right duplicates',
    fn: function () {
      //       0
      //      / \
      //     1   1
      //    / \ / \
      //   2  3 2  3
      var root = arrayToTree([0, 1, 1, 2, 3, 2, 3]);
      var dupes = find_duplicates(root);
      assert.strictEqual(dupes.length, 2);
      var vals = sortedVals(dupes);
      assert.deepStrictEqual(vals, [1, 2]); // subtrees rooted at 1 and leaf 2
    }
  },
  {
    name: 'find_duplicates: negative values',
    fn: function () {
      //    -1
      //    / \
      //  -2  -2
      var root = arrayToTree([-1, -2, -2]);
      var dupes = find_duplicates(root);
      assert.strictEqual(dupes.length, 1);
      assert.strictEqual(dupes[0].val, -2);
    }
  },
  {
    name: 'find_duplicates: serialize output is consistent',
    fn: function () {
      var root = arrayToTree([1, 2, 3, 4, 5]);
      var s1 = serialize(root);
      var s2 = serialize(root);
      assert.strictEqual(s1, s2, 'same tree serializes identically');
    }
  },
];

var passed = 0;
var failed = 0;

tests.forEach(function (t) {
  try {
    t.fn();
    passed++;
    console.log('  PASS: ' + t.name);
  } catch (e) {
    failed++;
    console.error('  FAIL: ' + t.name);
    console.error('    ' + e.message);
  }
});

console.log('\n' + passed + ' passed, ' + failed + ' failed');
process.exit(failed > 0 ? 1 : 0);

